-- Deterministic initial configuration. Re-running never resets owner switches or budgets.
begin;
on conflict(state_code) do nothing;
select state_code,'state',state_name,'{"source":"US state configuration"}'::jsonb from source_state_settings
on conflict(state_code,kind,name) do nothing;
on conflict(state_code,kind,name) do nothing;
select g.id,g.state_code,c.category from source_geographies g cross join unnest(array['COUNTY_PROGRAMS','MUNICIPAL_PROGRAMS','CRA','COMMUNITY_FOUNDATION','PRIVATE_FOUNDATION','CORPORATE_GIVING','BANK_CREDIT_UNION','UTILITY_COOP','HOSPITAL_HEALTH','TOURISM','WORKFORCE','ARTS_CULTURE','ENVIRONMENT','AGRICULTURE','FAITH_BASED','ASSOCIATIONS','HOUSING_COMMUNITY_DEVELOPMENT','YOUTH_EDUCATION']) c(category)
on conflict(geography_id,category) do nothing;
commit;
